            border: none;
            padding: 10px 20px;
            border-radius: 20px;
            cursor: pointer;
            font-weight: bold;
        }

        button.add-btn:hover {
            opacity: 0.9;
        }

        /* Modal do Carrinho */
        .cart-modal {
            display: none;
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background-color: rgba(0,0,0,0.5);
            z-index: 2000;
            justify-content: flex-end;
        }

        .cart-content {
            background-color: white;
            width: 90%;
            max-width: 400px;
            height: 100%;
            padding: 20px;
