                Total: <span id="cartTotal">R$ 0,00</span>
            </div>
            <button class="checkout-btn" onclick="alert('Pedido enviado para o finalista!')">Finalizar Pedido</button>
        </div>
    </div>

    <script>
        // --- LÓGICA JAVASCRIPT ---

        let cart = [];
        const cartBadge = document.getElementById('cart-badge');
        const cartItemsContainer = document.getElementById('cartItemsContainer');
        const cartTotalElement = document.getElementById('cartTotal');
        const cartModal = document.getElementById('cartModal');

        // Função para mostrar/esconder o carrinho
        function toggleCart() {
            if (cartModal.style.display === 'flex') {
                cartModal.style.display = 'none';
            } else {
                cartModal.style.display = 'flex';
                renderCart(); // Atualiza a tela ao abrir
            }
        }

        // Função para adicionar item
        function addToCart(name, price) {
            cart.push({ name, price });
            updateCartCount();

            // Feedback visual rápido no botão
            const btn = event.target;
            const originalText = btn.innerText;
            btn.innerText = "Adicionado!";
            btn.style.backgroundColor = "#4CAF50"; // Verde

            setTimeout(() => {
                btn.innerText = originalText;
                btn.style.backgroundColor = ""; // Volta ao original
            }, 1000);
        }

        // Atualiza o contador vermelho no ícone
        function updateCartCount() {
            cartBadge.innerText = cart.length;
            cartBadge.style.display = 'block';
        }

        // Remove itens duplicados da lista se clicado na quantidade (implementação simplificada apenas remove o último)
        // Para um sistema robusto, seria melhor ter uma lógica de quantidades
        // Aqui removemos tudo só para exemplo visual ao fechar/calcular

        // Renderiza a lista dentro do modal
        function renderCart() {
            cartItemsContainer.innerHTML = '';
            let total = 0;

            if (cart.length === 0) {
                cartItemsContainer.innerHTML = '<p style="text-align: center; color: #777;">Sua sacola está vazia.</p>';
            } else {
                cart.forEach((item, index) => {
                    total += item.price;

                    const itemDiv = document.createElement('div');
                    itemDiv.className = 'cart-item';
                    itemDiv.innerHTML = `
                        <div>
                            <strong>${item.name}</strong><br>
                            R$ ${item.price.toFixed(2)}
                        </div>
                        <button onclick="removeItem(${index})" style="background:red; color:white; border:none; border-radius:50%; width:25px; height:25px; cursor:pointer;">&times;</button>
                    `;
                    cartItemsContainer.appendChild(itemDiv);
                });
            }

            cartTotalElement.innerText = `R$ ${total.toFixed(2)}`;
        }

        // Remover um item específico (último adicionado por enquanto)
        function removeItem(index) {
            cart.splice(index, 1);
            updateCartCount();
            renderCart();
        }

    </script>
</body>
</html>
```

### Principais características deste código:

1.  **Ícone Flutuante (Sacola):** No canto inferior direito (`position: fixed`), há um botão laranja com um ícone de sacola. Ele acompanha o usuário rolando a página. Se houver itens na sacola, ele mostra um número vermelho.
2.  **Adicionar à Sacola:** Ao clicar nos botões "Adicionar" nos cards dos produtos, o nome e o preço vão para a memória temporária (array `cart`).
